import{_ as r}from"./chunks/architecture.Cs8uKTTN.js";import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"System Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/architecture.md","filePath":"dev-guide/architecture.md","lastUpdated":1787586465000}'),s={name:"dev-guide/architecture.md"};function n(c,e,l,d,p,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h1><p>Lertaro is built upon a multi-process isolation model and a layered architecture, ensuring sub-millisecond retrieval speeds and deep desktop integration while maintaining maximum system stability and security.</p><p><img src="'+r+'" alt="Lertaro Architecture"></p><h2 id="_1-three-process-isolation-model" tabindex="-1">1. Three-Process Isolation Model <a class="header-anchor" href="#_1-three-process-isolation-model" aria-label="Permalink to &quot;1. Three-Process Isolation Model&quot;">​</a></h2><p>To prevent single component failures from crashing the entire system and to minimize elevated Windows privileges, Lertaro&#39;s runtime is decoupled into three independent processes:</p><h3 id="_1-background-indexing-service-lertaro-service" tabindex="-1">1. Background Indexing Service (<code>Lertaro.Service</code>) <a class="header-anchor" href="#_1-background-indexing-service-lertaro-service" aria-label="Permalink to &quot;1. Background Indexing Service (`Lertaro.Service`)&quot;">​</a></h3><ul><li><strong>Identity</strong>: Runs continuously as a Windows Service under the <code>LocalSystem</code> account.</li><li><strong>Responsibilities</strong>: Performs disk indexing and change tracking. Reads NTFS / ReFS USN Change Journals and $MFT tables; listens to FAT32 / exFAT change events; periodically crawls and caches SMB / NAS network shares.</li><li><strong>Security &amp; Performance</strong>: Running at the SYSTEM level allows raw disk volume metadata access without prompting UAC dialogs, returning results to the user-mode App over high-speed named pipes while keeping the UI unprivileged.</li></ul><h3 id="_2-user-interaction-application-lertaro-app" tabindex="-1">2. User Interaction Application (<code>Lertaro.App</code>) <a class="header-anchor" href="#_2-user-interaction-application-lertaro-app" aria-label="Permalink to &quot;2. User Interaction Application (`Lertaro.App`)&quot;">​</a></h3><ul><li><strong>Identity</strong>: Standard user-mode per-session WPF desktop application.</li><li><strong>Responsibilities</strong>: Hosts the centered Quick Search bar, Full Search window, Settings Center, global hotkey dispatching, action menus (<code>Ctrl+O</code>), and QuickLook preview panels.</li><li><strong>IPC Bridge &amp; CLI Hosting</strong>: Communicates with the background service via bidirectional named pipes (<code>Core.Services.SearchService</code>). It also hosts a dedicated per-user named pipe (<code>AppSearchPipeService</code>), allowing external tools like the <code>lff</code> CLI companion to reuse the App&#39;s initialized memory aliases, plugin providers, and cache trees without separate initialization.</li></ul><h3 id="_3-global-keyboard-hook-window-adapter-process-lertaro-service-hook" tabindex="-1">3. Global Keyboard Hook &amp; Window Adapter Process (<code>Lertaro.Service --hook</code>) <a class="header-anchor" href="#_3-global-keyboard-hook-window-adapter-process-lertaro-service-hook" aria-label="Permalink to &quot;3. Global Keyboard Hook &amp; Window Adapter Process (`Lertaro.Service --hook`)&quot;">​</a></h3><ul><li><strong>Identity</strong>: Dedicated helper process launched with appropriate privileges by the background service.</li><li><strong>Responsibilities</strong>: Hosts low-level global keyboard hooks and mouse activity listeners.</li><li><strong>UIPI Bypass &amp; Crash Isolation</strong>: Windows User Interface Privilege Isolation (UIPI) prohibits lower-integrity user applications from sending messages to elevated administrator windows. By hosting window adapters (<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, <code>IInlineSearchAdapter</code></a>) inside this process, Lertaro hooks into Administrator-run Explorers, Total Commander, and file dialogs seamlessly. Furthermore, anti-cheat hooks or crashes cannot bring down the main UI.</li></ul><h2 id="_2-shared-core-library-lertaro-core" tabindex="-1">2. Shared Core Library (<code>Lertaro.Core</code>) <a class="header-anchor" href="#_2-shared-core-library-lertaro-core" aria-label="Permalink to &quot;2. Shared Core Library (`Lertaro.Core`)&quot;">​</a></h2><p><code>Lertaro.Core</code> is referenced simultaneously by the Service, App, and Hook processes, containing:</p><ul><li><strong>fzf Fuzzy Matching Engine (<code>Core/SearchIndex/Fzf/*</code>)</strong>: Optimized character jump matching, substring scoring, and highlight masks, coupled with <code>SearchQueryParser</code> for drive letters and path tokens.</li><li><strong>Columnar In-Memory Index (<code>Core/IndexV2/*</code>)</strong>: High-performance memory-mapped columnar snapshots with an in-memory delta overlay for sub-millisecond searches across hundreds of millions of files.</li><li><strong>Binary IPC Protocols</strong>: Standard serialized message structures (<code>SearchRequestMessage</code>, binary serializers) enabling zero-copy inter-process communication.</li><li><strong>Multi-Process Logging (<code>Logger</code>)</strong>: Structured logging output to <code>service.log</code>, <code>app.log</code>, and <code>hook.log</code>, presented uniformly within the Settings live log viewer.</li></ul><h2 id="_3-plugin-architecture-lifecycle" tabindex="-1">3. Plugin Architecture &amp; Lifecycle <a class="header-anchor" href="#_3-plugin-architecture-lifecycle" aria-label="Permalink to &quot;3. Plugin Architecture &amp; Lifecycle&quot;">​</a></h2><p>All plugins are built on <code>Lertaro.PluginSdk</code> and dynamically loaded by <code>Lertaro.App</code>:</p><ul><li><strong>Zero-Privilege Direct Access</strong>: Plugins interact exclusively with the App process. If a plugin requires custom directory indexing, it delegates requests through <code>DirectoryIndexerService</code>.</li><li><strong>Dual-Loading Mechanism</strong>: Search sources, actions, and UI components run solely in the App process; window and file dialog adapters (<code>IActivePathCollector</code> etc.) are also loaded into the Hook process to handle cross-integrity window automation.</li></ul>',17)])])}const y=o(s,[["render",n]]);export{m as __pageData,y as default};
